  lp.setExtra((r) => { const t = $("#res", el).querySelector(".pager"); if (t) t.insertAdjacentHTML("afterbegin", `<span><strong>Approved total: ${naira(r.approved_total_kobo)}</strong></span>`); });
  const n = $("#e-new", el); if (n) n.onclick = () => openForm({ title: "Record expense", fields: [sel("category_id", "Category", opts(cats), { numeric: true, required: true }), sel("branch_id", "Branch", branchOpts(), { numeric: true, required: true }), { name: "description", label: "Description", required: true, span: true }, { name: "amount_kobo", label: "Amount (₦)", type: "money", required: true }, { name: "expense_date", label: "Date", type: "date", value: todayISO() }, { name: "supporting_ref", label: "Receipt / reference no." }, { html: `<label class="f">Receipt photo (optional)<input type="file" accept="image/*,application/pdf" id="ex-f"></label>` }],
    onSubmit: async (v, m) => { const r = await api("/expenses", { method: "POST", body: { ...v, category_id: Number(v.category_id), branch_id: Number(v.branch_id), expense_date: v.expense_date || null } }); const f = $("#ex-f", m.el)?.files[0]; if (f) { const fd = new FormData(); fd.append("file", f); await api(`/expenses/${r.id}/attachment`, { method: "POST", form: fd }); } m.close(); toast(r.status === "pending_approval" ? "Recorded - awaiting approval" : "Expense recorded", "ok"); lp.refresh(); } });
  el.addEventListener("click", (e) => { const d = e.target.closest("[data-ex]"), a = e.target.closest("[data-at]");
    if (d) openForm({ title: d.dataset.ok === "1" ? "Approve expense" : "Reject expense", fields: [{ name: "note", label: "Note", span: true }], onSubmit: async (v, m) => { await api(`/expenses/${d.dataset.ex}/decide`, { method: "POST", body: { approve: d.dataset.ok === "1", note: v.note } }); m.close(); toast("Done", "ok"); lp.refresh(); } });
    if (a) { const inp = document.createElement("input"); inp.type = "file"; inp.accept = "image/*,application/pdf"; inp.onchange = async () => { const fd = new FormData(); fd.append("file", inp.files[0]); try { await api(`/expenses/${a.dataset.at}/attachment`, { method: "POST", form: fd }); toast("Attached", "ok"); } catch (er) { toast(er.message, "bad"); } }; inp.click(); } });
