// ================= reports =================
export async function reports(el) {
  await branchList(); const cat = await api("/reports");
  mount(el, h`<div class="page-head"><div><h1>Reports</h1><p>Run a report, review it here, then export it as CSV or PDF.</p></div></div><div class="filters"><label class="f">Report<select id="rp">${cat.map((c) => h`<option value="${c.key}">${c.title}</option>`)}</select></label><label class="f">Branch<select id="rb">${branchOpts("All").map((o) => h`<option value="${o.value}">${o.label}</option>`)}</select></label><label class="f">From<input type="date" id="rf" value="${todayISO().slice(0, 8)}01"></label><label class="f">To<input type="date" id="rt" value="${todayISO()}"></label>
    <div class="row"><button class="btn primary" id="run">Run report</button>${can("reports.export") ? h`<button class="btn" id="csv">${icon("download")} CSV</button><button class="btn" id="pdf">${icon("doc")} PDF</button>` : ""}</div></div><div class="card flush" id="out"><div class="empty">Choose a report and press Run.</div></div>`);
  const params = () => ({ branch_id: $("#rb", el).value, date_from: $("#rf", el).value, date_to: $("#rt", el).value });
  $("#run", el).onclick = async () => { const o = $("#out", el); mount(o, loading()); try { const d = await api(`/reports/${$("#rp", el).value}`, { params: params() });
    mount(o, h`<div class="card-head"><h3 style="margin:0">${d.title}</h3><span class="muted small">${d.range}</span></div>${Object.keys(d.summary || {}).length ? h`<div class="row" style="padding:10px 16px;flex-wrap:wrap">${Object.entries(d.summary).map(([k, v]) => h`<span class="badge">${title(k)}: ${v}</span>`)}</div>` : ""}${d.rows.length ? h`<div class="tbl-wrap"><table class="tbl cards"><thead><tr>${d.columns.map((c) => h`<th>${c}</th>`)}</tr></thead><tbody>${d.rows.map((r) => h`<tr>${r.map((c, i) => h`<td data-l="${d.columns[i]}">${c}</td>`)}</tr>`)}</tbody></table></div>` : h`<div class="empty">No data for this period.</div>`}`); } catch (e) { mount(o, errorBox(e)); } };
  const csv = $("#csv", el); if (csv) csv.onclick = async () => { try { await download(`/reports/${$("#rp", el).value}`, { ...params(), format: "csv" }, `${$("#rp", el).value}.csv`); } catch (e) { toast(e.message, "bad"); } };
  const pdf = $("#pdf", el); if (pdf) pdf.onclick = () => openPdf(`/reports/${$("#rp", el).value}`, { ...params(), format: "pdf" }).catch((e) => toast(e.message, "bad"));
}

// ================= staff =================
export async function staffPage(el) {
  await branchList(); const R = await api("/roles"); const roles = R.roles.filter((r) => r.is_staff);
  const form = async (u = {}) => { const d = u.id ? await api(`/staff/${u.id}`) : {};
    openForm({ title: u.id ? "Edit staff member" : "New staff member", wide: true, values: d, fields: [{ name: "full_name", label: "Full name", required: true }, ...(u.id ? [] : [{ name: "email", label: "Email (login)", type: "email", required: true }]), { name: "phone", label: "Phone", type: "tel" }, { name: "employee_id", label: "Employee ID" }, sel("role_key", "Role", roles.map((r) => ({ value: r.key, label: r.name })), { value: d.role }), sel("branch_id", "Branch", none(branchOpts()), { numeric: true, nullable: true }), { name: "department", label: "Department" }, { name: "job_title", label: "Job title" }, { name: "work_schedule", label: "Work schedule" },
      ...(u.id ? [{ name: "is_active", label: "Account active", type: "checkbox", value: d.is_active }] : [{ name: "license_no", label: "Licence no. (drivers)" }, { name: "password", label: "Initial password", type: "password", hint: "Leave blank to generate a temporary password" }]),
      { html: `<div><strong>Extra branch access</strong><div class="row" style="flex-wrap:wrap;gap:10px;margin-top:6px">${state.staffBranches.map((b) => `<label class="check"><input type="checkbox" data-xb="${b.id}" ${(d.extra_branch_ids || []).includes(b.id) ? "checked" : ""}> ${esc(b.name)}</label>`).join("")}</div></div>` },
      ...(u.id && can("roles.manage") ? [{ html: `<div><strong>Individual permission overrides</strong><p class="muted small">Tick to grant beyond the role; “deny” removes a permission this person would otherwise have.</p><div class="perm-grid">${R.permissions.map((p) => { const has = (d.permissions || []).includes(p.key), ov = d.overrides?.[p.key]; return `<label class="check small"><select data-ov="${p.key}"><option value="">${has ? "granted (role)" : "—"}</option><option value="1" ${ov === true ? "selected" : ""}>grant</option><option value="0" ${ov === false ? "selected" : ""}>deny</option></select> ${esc(p.key)}</label>`; }).join("")}</div></div>` }] : [])],
    onSubmit: async (v, m) => { v.branch_id = v.branch_id ? Number(v.branch_id) : null; v.extra_branch_ids = $$("[data-xb]:checked", m.el).map((i) => Number(i.dataset.xb));
      if (u.id) { const ov = {}; $$("[data-ov]", m.el).forEach((s) => { if (s.value !== "") ov[s.dataset.ov] = s.value === "1"; }); if ($$("[data-ov]", m.el).length) v.permission_overrides = ov; delete v.email; }
      else if (!v.password) delete v.password;
      const r = await api(u.id ? `/staff/${u.id}` : "/staff", { method: u.id ? "PATCH" : "POST", body: v }); m.close(); toast("Staff saved", "ok"); if (r.temporary_password) tempPw(r.full_name, r.temporary_password); staffPage(el); } }); };
  const tempPw = (name, pw) => modal({ title: "Temporary password", body: h`<p>Give this temporary password to <strong>${name}</strong>. It is shown <strong>once</strong>; they must change it at first sign-in.</p><div class="codebox">${pw}</div>` });
  const lp = listPage(el, { head: "Staff", desc: "Accounts, roles, branch access and permissions.", toolbar: `${can("roles.manage") ? '<button class="btn" id="roles">Role permissions</button>' : ""}${can("staff.manage") ? '<button class="btn primary" id="s-new">+ New staff</button>' : ""}`,
    filters: [{ name: "q", label: "Search", placeholder: "Name, email, ID" }, { name: "role", label: "Role", type: "select", options: [{ value: "", label: "All" }, ...roles.map((r) => ({ value: r.key, label: r.name }))] }, { name: "branch_id", label: "Branch", type: "select", options: branchOpts("All") }],
    load: (p, page, size) => api("/staff", { params: { ...p, page, size } }), cols: [{ label: "Staff", render: (u) => h`<strong>${u.full_name}</strong>${u.is_demo ? h` <span class="badge demo">Demo</span>` : ""}<div class="muted small">${u.email} ${u.phone}</div>` }, { label: "Role", render: (u) => u.role_name }, { label: "Branch", render: (u) => u.branch_name || "All" }, { label: "Last sign-in", render: (u) => u.last_login ? fdt(u.last_login) : "never" }, { label: "Status", render: (u) => badge(u.is_active ? "active" : "inactive") }],
    onRow: can("staff.manage") ? (u) => { const m = modal({ title: u.full_name, body: h`<p class="muted">${u.email} · ${u.role_name}</p><div class="row"><button class="btn primary" id="ed">${icon("edit")} Edit</button><button class="btn" id="rs">Reset password</button><button class="btn" id="rv">Sign out everywhere</button></div>` });
      $("#ed", m.el).onclick = () => { m.close(); form(u); }; $("#rs", m.el).onclick = async () => { if (!(await confirmDialog(`Reset the password for ${u.full_name}?`, { okLabel: "Reset" }))) return; try { const r = await api(`/staff/${u.id}/reset-password`, { method: "POST" }); m.close(); tempPw(u.full_name, r.temporary_password); } catch (e) { toast(e.message, "bad"); } }; $("#rv", m.el).onclick = async () => { try { await api(`/staff/${u.id}/revoke-sessions`, { method: "POST" }); toast("Signed out", "ok"); } catch (e) { toast(e.message, "bad"); } }; } : null });
  const n = $("#s-new", el); if (n) n.onclick = () => form();
  const rb = $("#roles", el); if (rb) rb.onclick = () => { const mods = [...new Set(R.permissions.map((p) => p.module))]; const m = modal({ title: "Role permissions", wide: true, body: h`<p class="muted">Pick a role and tick what it may do. The Super Administrator always has every permission. Changes sign affected users out.</p><label class="f">Role<select id="rr">${roles.filter((r) => r.key !== "super_admin").map((r) => h`<option value="${r.key}">${r.name}</option>`)}</select></label><div id="rp-grid"></div><div class="row" style="margin-top:12px"><button class="btn primary" id="rp-save">Save permissions</button></div>` });
    const draw = () => { const r = roles.find((x) => x.key === $("#rr", m.el).value); mount($("#rp-grid", m.el), h`${mods.map((mod) => h`<h4 style="margin:12px 0 4px">${title(mod)}</h4><div class="perm-grid">${R.permissions.filter((p) => p.module === mod).map((p) => h`<label class="check small"><input type="checkbox" data-pk="${p.key}" ${r.permissions.includes(p.key) ? raw("checked") : ""}> ${p.description}</label>`)}</div>`)}`); };
    $("#rr", m.el).onchange = draw; draw(); $("#rp-save", m.el).onclick = async () => { const key = $("#rr", m.el).value; const permissions = $$("[data-pk]:checked", m.el).map((i) => i.dataset.pk); try { await api(`/roles/${key}/permissions`, { method: "PUT", body: { permissions } }); roles.find((x) => x.key === key).permissions = permissions; toast("Permissions saved", "ok"); } catch (e) { toast(e.message, "bad"); } }; };
}

// ================= tasks =================
const TASK_NEXT = { assigned: [["accepted", "Accept"], ["needs_review", "Report problem"]], accepted: [["in_progress", "Start"], ["needs_review", "Report problem"]], in_progress: [["completed", "Mark complete"], ["needs_review", "Report problem"]], needs_review: [], completed: [] };
function taskCard(t, mine, refresh) {
  const mgr = can("tasks.manage");
  return h`<div class="card"><div class="row between"><strong>${t.title}</strong>${badge(t.priority)}</div><p class="muted small">${t.instructions}</p><div class="small muted">${t.assignee ? "To " + t.assignee + " · " : ""}${t.due_at ? "Due " + fdt(t.due_at) : "No due date"} · ${badge(t.status)}</div>${t.completion_notes ? h`<p class="small">✔ ${t.completion_notes}</p>` : ""}${t.problem_report ? h`<p class="small" style="color:var(--red)">⚠ ${t.problem_report}</p>` : ""}${t.review_note ? h`<p class="small">Manager note: ${t.review_note}</p>` : ""}
    <div class="row" style="margin-top:8px">${mine ? (TASK_NEXT[t.status] || []).map(([s, l]) => h`<button class="btn sm ${s === "completed" ? "primary" : ""}" data-tk="${t.id}" data-s="${s}">${l}</button>`) : ""}${mgr && !mine && t.status !== "completed" ? h`<button class="btn sm success" data-tk="${t.id}" data-s="completed" data-mgr="1">Sign off</button><button class="btn sm" data-tk="${t.id}" data-s="needs_review" data-mgr="1">Send back</button>` : ""}</div></div>`;
}
function bindTasks(root, refresh) {
  root.addEventListener("click", (e) => { const b = e.target.closest("[data-tk]"); if (!b) return; const id = b.dataset.tk, s = b.dataset.s, body = { status: s };
    const go = async (extra) => { try { await api(`/tasks/${id}`, { method: "PATCH", body: { ...body, ...extra } }); toast("Task updated", "ok"); refresh(); } catch (er) { toast(er.message, "bad"); } };
    if (s === "completed" && !b.dataset.mgr) openForm({ title: "Complete task", fields: [{ name: "completion_notes", label: "What was done?", type: "textarea", required: true, span: true }], onSubmit: async (v, m) => { m.close(); await go({ completion_notes: v.completion_notes }); } });
    else if (s === "needs_review" && !b.dataset.mgr) openForm({ title: "Report a problem", fields: [{ name: "problem_report", label: "Describe the problem", type: "textarea", required: true, span: true }], onSubmit: async (v, m) => { m.close(); await go({ problem_report: v.problem_report }); } });
    else if (b.dataset.mgr && s === "needs_review") openForm({ title: "Send back for rework", fields: [{ name: "review_note", label: "What should change?", type: "textarea", required: true, span: true }], onSubmit: async (v, m) => { m.close(); await go({ review_note: v.review_note }); } });
    else go(); });
}
export async function tasksManage(el) {
  await branchList(); const staff = (await api("/staff", { params: { size: 200 } }).catch(() => ({ items: [] }))).items;
  const draw = async () => { const list = await api("/tasks", { params: { mine: false } });
    mount(el, h`<div class="page-head"><div><h1>Tasks</h1><p>Assign work to a person or a whole department and follow it to completion.</p></div><button class="btn primary" id="t-new">+ Assign task</button></div>${list.length ? h`<div class="grid3">${list.map((t) => taskCard(t, false))}</div>` : h`<div class="empty">No tasks yet.</div>`}`);
    $("#t-new", el).onclick = () => openForm({ title: "Assign task", wide: true, fields: [{ name: "title", label: "Title", required: true, span: true }, { name: "instructions", label: "Instructions", type: "textarea", span: true }, sel("priority", "Priority", ["low", "normal", "high", "urgent"].map((x) => ({ value: x, label: title(x) })), { value: "normal" }), { name: "due_at", label: "Due", type: "datetime-local" }, sel("assigned_to", "Assign to person", none(staff.map((s) => ({ value: s.id, label: `${s.full_name} (${s.role_name})` }))), { numeric: true, nullable: true }), { name: "department", label: "…or to a department", hint: "Creates one task per member" }, sel("branch_id", "Branch", none(branchOpts()), { numeric: true, nullable: true })],
      onSubmit: async (v, m) => { v.assigned_to = v.assigned_to ? Number(v.assigned_to) : null; v.branch_id = v.branch_id ? Number(v.branch_id) : null; v.due_at = v.due_at ? new Date(v.due_at).toISOString() : null; await api("/tasks", { method: "POST", body: v }); m.close(); toast("Task assigned", "ok"); draw(); } }); };
  bindTasks(el, draw); draw();
}

// ================= workspace (my work) =================
export async function workspace(el) {
  const draw = async () => { const [w, tasks] = await Promise.all([api("/workspace"), api("/tasks", { params: { mine: true } })]); const open = tasks.filter((t) => t.status !== "completed");
    mount(el, h`<div class="page-head"><div><h1>My workspace</h1><p>Hello, ${w.profile.full_name}. ${w.profile.role_name}${w.profile.branch_name ? " · " + w.profile.branch_name : ""}</p></div></div>
      <div class="stats">${[["To do", (w.task_counts.assigned || 0) + (w.task_counts.accepted || 0)], ["In progress", w.task_counts.in_progress || 0], ["Awaiting review", w.task_counts.needs_review || 0], ["Completed", w.task_counts.completed || 0], ["Overdue", w.overdue], ["Unread notifications", w.unread_notifications]].map(([l, v]) => h`<div class="stat ${l === "Overdue" && v ? "warn" : ""}"><div class="l">${l}</div><div class="v">${v}</div></div>`)}</div>
      <h3 style="margin:18px 0 8px">My open tasks</h3>${open.length ? h`<div class="grid3">${open.map((t) => taskCard(t, true))}</div>` : h`<div class="empty">Nothing assigned to you right now.</div>`}
      <div class="grid2" style="margin-top:18px"><div class="card"><h3>My profile</h3><dl class="kv"><dt>Email</dt><dd>${w.profile.email}</dd><dt>Phone</dt><dd>${w.profile.phone || "-"}</dd><dt>Employee ID</dt><dd>${w.profile.employee_id || "-"}</dd><dt>Department</dt><dd>${w.profile.department || "-"}</dd><dt>Schedule</dt><dd>${w.profile.work_schedule || "-"}</dd></dl></div><div class="card"><h3>My recent activity</h3><ul class="plain">${w.activity.length ? w.activity.map((a) => h`<li>${title(a.action)} <span class="muted small">${a.entity} ${a.entity_id} · ${fdt(a.at)}</span></li>`) : h`<li class="muted">No activity yet.</li>`}</ul></div></div>`); };
  bindTasks(el, draw); draw();
}

// ================= audit =================
export async function audit(el) {
  listPage(el, { head: "Audit log", desc: "Who did what, and when. Entries cannot be edited or deleted.", filters: [{ name: "q", label: "Search", placeholder: "User or record" }, { name: "action", label: "Action", placeholder: "e.g. login_failed" }],
    load: (p, page, size) => api("/audit-logs", { params: { ...p, page, size } }), size: 50, cols: [{ label: "When", render: (a) => fdt(a.at) }, { label: "User", key: "user" }, { label: "Action", render: (a) => title(a.action) }, { label: "Record", render: (a) => `${a.entity} ${a.entity_id}` }, { label: "Details", render: (a) => h`<code class="small">${a.details && Object.keys(a.details).length ? JSON.stringify(a.details).slice(0, 140) : ""}</code>` }, { label: "IP", key: "ip" }] });
}

// ================= settings =================
export async function settings(el) {
  const d = await api("/settings"); const s = d.settings; const mg = can("settings.manage");
  const k = (key, label, type = "text", extra = {}) => ({ name: key, label, type, value: s[key], ...extra });
  const groups = [
    ["Business", [k("business_name", "Business name"), k("tagline", "Tagline"), k("contact_phone", "Phone"), k("contact_email", "Email"), k("contact_address", "Address"), k("timezone", "Time zone")]],
    ["Orders & delivery", [k("order_prefix", "Order number prefix"), k("delivery_fee_kobo", "Delivery fee (₦)", "money"), k("free_delivery_above_kobo", "Free delivery above (₦, 0 = never)", "money"), k("min_order_kobo", "Minimum order (₦)", "money"), k("tax_enabled", "Charge tax", "checkbox"), k("tax_rate_percent", "Tax rate %", "number", { step: "any" }), { name: "delivery_lgas", label: "Delivery areas (one per line)", type: "textarea", span: true, value: (s.delivery_lgas || []).join("\n") }, { name: "delivery_time_slots", label: "Delivery time slots (one per line)", type: "textarea", span: true, value: (s.delivery_time_slots || []).join("\n") }]],
    ["Payments", [k("pay_cash_on_delivery", "Cash on delivery", "checkbox"), k("pay_cash_at_pickup", "Cash at pickup", "checkbox"), k("pay_bank_transfer", "Bank transfer", "checkbox"), k("pay_online", "Online payment (needs Paystack keys on the server)", "checkbox"), k("bank_name", "Bank name"), k("bank_account_number", "Account number"), k("bank_account_name", "Account name")]],
    ["Finance & costing", [k("expense_approval_threshold_kobo", "Expense approval threshold (₦)", "money", { hint: "Expenses at or above this need approval" }), k("overhead_percent_of_ingredient_cost", "Overhead % added to recipe cost", "number", { step: "any" })]],
    ["Notifications", [k("low_stock_alerts", "Low-stock alerts", "checkbox"), k("notify_email", "Email notifications (requires server configuration)", "checkbox"), k("notify_sms", "SMS notifications (requires provider)", "checkbox"), k("notify_whatsapp", "WhatsApp notifications (requires provider)", "checkbox")]],
  ];
  mount(el, h`<div class="page-head"><div><h1>Settings</h1><p>Business-wide configuration. Changes are audited.</p></div></div>
    ${can("settings.manage") && state.user.role === "super_admin" ? h`<div class="card" style="margin-bottom:16px;border-left:4px solid ${s.data_mode === "demo" ? "var(--orange)" : "var(--green)"}"><div class="row between"><div><h3 style="margin:0">Data mode: ${s.data_mode === "demo" ? "DEMO" : "LIVE"}</h3><p class="muted small" style="margin:4px 0 0">Demo data is stored separately and never mixes with live records. ${s.data_mode === "demo" ? "You are viewing sample data." : "You are viewing real business data."}</p></div><button class="btn" id="mode">Switch to ${s.data_mode === "demo" ? "live" : "demo"}</button></div></div>` : ""}
    <div class="grid2">${groups.map(([g], i) => h`<div class="card"><div class="row between"><h3 style="margin:0">${g}</h3>${mg ? h`<button class="btn sm" data-g="${i}">${icon("edit")} Edit</button>` : ""}</div><dl class="kv" style="margin-top:8px">${groups[i][1].map((f) => h`<dt>${f.label.replace(/ \(.*\)/, "")}</dt><dd>${f.type === "checkbox" ? (s[f.name] ? "On" : "Off") : f.type === "money" ? naira(s[f.name]) : f.type === "textarea" ? (s[f.name] || []).join(", ") : s[f.name] || "-"}</dd>`)}</dl></div>`)}
    <div class="card"><div class="row between"><h3 style="margin:0">Expense categories</h3>${mg ? h`<button class="btn sm" id="ec-new">+ Add</button>` : ""}</div><ul class="plain">${d.expense_categories.map((c) => h`<li>${c.name} ${c.counts_in_cogs ? h`<span class="badge">cost of goods</span>` : ""} ${c.is_active ? "" : h`<span class="badge">inactive</span>`} ${mg ? h`<button class="btn sm" data-ec="${c.id}">${icon("edit")}</button>` : ""}</li>`)}</ul></div></div>`);
  const save = async (values) => { await api("/settings", { method: "PUT", body: { values } }); };
  el.onclick = async (e) => {
    const g = e.target.closest("[data-g]"), ec = e.target.closest("[data-ec]");
    if (g) { const [name, fields] = groups[g.dataset.g]; openForm({ title: name, wide: true, fields, onSubmit: async (v, m) => { const out = {}; for (const f of fields) { let x = v[f.name]; if (f.type === "money" || f.type === "number") x = Number(x || 0); if (f.name === "delivery_lgas" || f.name === "delivery_time_slots") x = String(x).split("\n").map((t) => t.trim()).filter(Boolean); if (f.name === "overhead_percent_of_ingredient_cost" || f.name === "tax_rate_percent") x = Number(x); out[f.name] = x; } await save(out); m.close(); toast("Settings saved", "ok"); settings(el); } }); }
    if (e.target.closest("#mode")) { const to = s.data_mode === "demo" ? "live" : "demo"; if (!(await confirmDialog(`Switch to ${to.toUpperCase()} data? You will see only ${to} records.`, { okLabel: "Switch" }))) return; try { await save({ data_mode: to }); toast("Switched to " + to + " mode", "ok"); location.reload(); } catch (er) { toast(er.message, "bad"); } }
    if (e.target.closest("#ec-new") || ec) { const c = ec ? d.expense_categories.find((x) => x.id == ec.dataset.ec) : {}; openForm({ title: "Expense category", values: c, fields: [{ name: "name", label: "Name", required: true }, { name: "counts_in_cogs", label: "Counts as cost of goods (raw materials / packaging)", type: "checkbox", value: !!c.counts_in_cogs }, { name: "is_active", label: "Active", type: "checkbox", value: c.id ? c.is_active : true }], onSubmit: async (v, m) => { await api(c.id ? `/settings/expense-categories/${c.id}` : "/settings/expense-categories", { method: c.id ? "PUT" : "POST", body: v }); m.close(); toast("Saved", "ok"); settings(el); } }); }
  };
}

// ================= notifications =================
export async function notifications(el) {
  const draw = async () => { const d = await api("/notifications");
    mount(el, h`<div class="page-head"><div><h1>Notifications</h1><p>${d.unread} unread. In-app only - email, SMS and WhatsApp are not active unless configured on the server.</p></div>${d.unread ? h`<button class="btn" id="all">Mark all read</button>` : ""}</div><div class="card flush">${d.items.length ? d.items.map((n) => h`<a class="notice ${n.is_read ? "" : "unread"}" href="${n.link || "#/notifications"}" data-n="${n.id}"><strong>${n.title}</strong><span class="muted small">${n.body}</span><span class="muted small">${fdt(n.created_at)}</span></a>`) : h`<div class="empty">You're all caught up.</div>`}</div>`);
    const a = $("#all", el); if (a) a.onclick = async () => { await api("/notifications/read", { method: "POST" }); draw(); };
    el.onclick = async (e) => { const n = e.target.closest("[data-n]"); if (n) api("/notifications/read", { method: "POST", body: [Number(n.dataset.n)] }).catch(() => {}); }; };
  draw();
}
